<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useApplication} from '../../application';import {localTime,stateLabels,usageLabels} from './workbench-types';
const props=defineProps<{id:string;canReview:boolean}>(),emit=defineEmits<{changed:[]}>(),app=useApplication(),actions=app.feedbackActions,detail=actions.detail,error=ref(''),reason=ref(''),decision=ref('ACCEPTED');let epoch=0;
const locked=computed(()=>actions.busy.value||actions.pending.value||!actions.available.value),current=computed(()=>detail.value?.feedback.id===props.id?detail.value:null);
async function load(){const turn=++epoch;error.value='';try{await actions.open(props.id);}catch(cause){if(turn===epoch)error.value=cause instanceof Error?cause.message:'详情暂不可用。';}}
async function run(action:()=>Promise<unknown>){error.value='';try{await action();reason.value='';emit('changed');}catch(cause){error.value=cause instanceof Error?cause.message:'审核尚未确认，请保留原请求。';}}
watch(()=>props.id,()=>void load(),{immediate:true});onUnmounted(()=>epoch++);
</script>
<template><p v-if="error" class="gov-error" role="alert">{{error}}</p><p v-if="actions.busy.value" role="status">正在核实反馈…</p><template v-if="current&&actions.available.value"><dl class="gov-definition"><dt>审核状态</dt><dd><span class="gov-tag" :data-state="current.feedback.state">{{stateLabels[current.feedback.state]}}</span></dd><dt>使用状态</dt><dd>{{current.usage?usageLabels[current.usage.usageState]:'—'}}</dd><template v-if="current.usage?.usageVersion"><dt>采用版本</dt><dd>{{current.usage.usageVersion}}</dd></template><template v-if="current.submission"><dt>原始值</dt><dd class="gov-copy">{{current.submission.originalValue}}</dd><dt>建议值</dt><dd class="gov-copy">{{current.submission.suggestedValue}}</dd><dt>说明</dt><dd class="gov-copy">{{current.submission.note||'—'}}</dd></template><template v-else><dt>提交内容</dt><dd class="gov-copy">{{current.feedback.comment}}</dd></template><dt>审核意见</dt><dd class="gov-copy">{{current.reviewReason||'等待审核'}}</dd><dt>来源版本</dt><dd>{{current.submission?.sourceRevisionToken??'—'}}</dd></dl><p class="gov-note">审核仅使用主动提交的内容。来源会议的访问权限保持由会议负责人管理。</p><h3>处理历史</h3><ol class="gov-history"><li v-for="item in current.history" :key="item.id"><b>{{({SUPPLEMENT:'补充说明',REVIEW:'审核',UNDO_REVIEW:'撤销审核',RESAMPLE:'重新采样'} as Record<string,string>)[item.action]}} · {{item.actorId}}</b><time>{{localTime(item.createdAt)}}</time><p>{{item.text||'恢复待审核'}}</p></li><li v-if="!current.history.length">尚无处理记录</li></ol><div v-if="canReview&&current.usage?.usageState!=='WITHDRAWN'" class="gov-fields"><label v-if="current.feedback.state==='PENDING'">审核结论<select v-model="decision" class="select" :disabled="locked"><option value="ACCEPTED">通过</option><option value="NEEDS_MORE">需要补充</option><option value="REJECTED">驳回</option></select></label><label v-if="current.feedback.state==='PENDING'">审核意见<textarea v-model="reason" class="textarea" maxlength="2048" :disabled="locked" placeholder="说明审核依据，或需要补充的具体内容"/></label><button v-if="current.feedback.state==='PENDING'" class="btn primary" :disabled="locked||!reason.trim()" @click="run(()=>actions.review(decision,reason))">提交审核</button><button v-else class="btn" :disabled="locked" @click="run(actions.undo)">撤销审核并恢复待审</button></div><p v-else-if="!canReview" class="gov-note">本人提交或涉及本人身份的记录由其他管理员审核。</p></template><section v-if="actions.pending.value" class="gov-note"><b>原审核操作待核实</b><p>已保留原请求，重新核实后才能继续处理。</p><button v-if="['PREPARED','UNCERTAIN','ACKNOWLEDGED'].includes(actions.command.state.value)" class="btn" :disabled="actions.busy.value||!actions.available.value" @click="run(actions.retry)">恢复原审核操作</button><button v-if="['CONFLICT','REJECTED'].includes(actions.command.state.value)" class="btn" @click="run(async()=>{actions.discardRejected();await actions.reload()})">关闭已拒绝请求并刷新</button></section></template>
